    @Test
    void parcelamentoInvalidoNoCartaoAcimaDe12DevolveErro() {
        ResumoRequest request = new ResumoRequest(
                List.of(camiseta()), "ECONOMICA", null, "CARTAO", 13, "BRONZE", "SUDESTE");

